		r = ((c1 & 0x0F) << 2) | ((c1 & 0x0F) >> 2);
		g = ((c2 & 0xF0) >> 2) | ((c2 & 0xF0) >> 6);
		b = ((c2 & 0x0F) >> 2) | ((c2 & 0x0F) << 2);
		m_palette->set_pen_color(i, pal6bit(r), pal6bit(g), pal6bit(b));
	}
}


