## Summary: MAME Another World VM Source Code

Based on my search, I found the reference MAME implementation at the GitHub repository you mentioned (felipesanches/mame commit 7cbb93bc3ee05f5ffdd083081530ac0daa2dfa84). Here is the complete source code for the functions you requested:

### 1. **op_condJmp (Conditional Jump - Opcode 0x0A)**

```cpp
case 0x0A: /* condJmp */
{
    uint8_t subopcode = fetch_byte();
    uint8_t v = fetch_byte();
    int16_t b = read_vm_variable(v);
    uint8_t c = fetch_byte();
    int16_t a;

    if (subopcode & 0x80)
        a = read_vm_variable(c);
    else if (subopcode & 0x40)
        a = c << 8 | fetch_byte();
    else
        a = c;

    // Check if the conditional value is met.
    bool expr = false;
    switch (subopcode & 7)
    {
        case 0: // jz
            expr = (b == a);
            break;
        case 1: // jnz
            expr = (b != a);
            break;
        case 2: // jg
            expr = (b > a);
            break;
        case 3: // jge
            expr = (b >= a);
            break;
        case 4: // jl
            expr = (b < a);
            break;
        case 5: // jle
            expr = (b <= a);
            break;
        default:
            printf("ERROR: conditional jump: invalid condition (%d)\n", (subopcode & 7));
            break;
    }

    uint16_t offset = fetch_word();
    if (expr)
        PC = offset;

    return;
}
```

### 2. **op_resetThread (Opcode 0x0C)**

```cpp
case 0x0C: /* resetThread */
{
    uint8_t first = fetch_byte();
    uint8_t last = fetch_byte();
    uint8_t type = fetch_byte();

    //Make sure last is within [0, NUM_THREADS-1]
    last = last % NUM_THREADS;

    if (last < first)
    {
        printf("ERROR: resetThread with last (%02X) < first (%02X).\n", last, first);
        return;
    }

    switch(type)
    {
        case RESET_TYPE__UNFREEZE_CHANNELS:
            for (int i=first; i<=last; i++)
                m_threads[i].requested_state = FROZEN;
            break;
        case RESET_TYPE__FREEZE_CHANNELS:
            for (int i=first; i<=last; i++)
                m_threads[i].requested_state = UNFROZEN;
            break;
        case RESET_TYPE__DELETE_CHANNELS:
            for (int i=first; i<=last; i++)
                m_threads[i].requested_PC = DELETE_THIS_THREAD;
            break;
        default:
            printf("ERROR: invalid resetThread operation type (%d).\n", type);
    }
    return;
}
```

### 3. **Opcode 0x40 (Extended Video Instruction)**

```cpp
if (opcode & 0x40)
{
    int16_t x, y;
    uint16_t offset = fetch_word() * 2;
    x = fetch_byte();

    m_useVideo2 = false;

    if (!(opcode & 0x20))
    {
        if (!(opcode & 0x10))
            x = (x << 8) | fetch_byte();
        else
            x = read_vm_variable(x);
    }
    else
    {
        if (opcode & 0x10)
            x += 0x100;
    }

    y = fetch_byte();

    if (!(opcode & 8))
    {
        if (!(opcode & 4))
            y = (y << 8) | fetch_byte();
        else
            y = read_vm_variable(y);
    }

    uint16_t zoom = 0x40;

    switch (opcode & 0x03)
    {
        case 0:
            zoom = 0x40;
            break;
        case 1:
            zoom = read_vm_variable(fetch_byte());
            break;
        case 2:
            fetch_byte();
            break;
        case 3:
            m_useVideo2 = true;
            zoom = 0x40;
            break;
    }

    ((another_world_vm_state*) owner())->setDataBuffer(m_useVideo2 ? VIDEO_2 : CINEMATIC, offset);
    ((another_world_vm_state*) owner())->readAndDrawPolygon(COLOR_BLACK, zoom, VMPoint(x, y));

    return;
}
```

