### 8. **input_updatePlayer**

```cpp
void another_world_cpu_device::input_updatePlayer()
{
    int16_t lr = 0;
    int16_t m = 0;
    int16_t ud = 0;
    int8_t input = m_read_input();

    write_vm_variable(VM_VARIABLE_LAST_KEYCHAR, m_read_keyboard());

    if (m_currentPartId != GAME_PART(0)
        && m_currentPartId != GAME_PART(9)
        && BIT(input, 4))
        m_requestedNextPart = GAME_PART(9);

    if (BIT(input, 2))
    {
        lr = 1;
        m |= 1;
    }

    if (BIT(input, 3))
    {
        lr = -1;
        m |= 2;
    }

    if (BIT(input, 0))
    {
        ud = 1;
        m |= 4;
    }

    if (BIT(input, 1))
    {
        write_vm_variable(VM_VARIABLE_HERO_POS_UP_DOWN, -1);
        ud = -1;
        m |= 8;
    }
    else
    {
        write_vm_variable(VM_VARIABLE_HERO_POS_UP_DOWN, ud);
    }

    write_vm_variable(VM_VARIABLE_HERO_POS_JUMP_DOWN, ud);
    write_vm_variable(VM_VARIABLE_HERO_POS_LEFT_RIGHT, lr);
    write_vm_variable(VM_VARIABLE_HERO_POS_MASK, m);

    int16_t button = 0;
    if (BIT(input, 7))
    {
        button = 1;
        m |= 0x80;
    }
    write_vm_variable(VM_VARIABLE_HERO_ACTION, button);
    write_vm_variable(VM_VARIABLE_HERO_ACTION_POS_MASK, m);
}
```

### 9. **copyVideoPage (with vscroll)**

```cpp
void another_world_vm_state::copyVideoPage(uint8_t srcPageId, uint8_t dstPageId, uint16_t vscroll)
{
    if (srcPageId == dstPageId)
        return;

    bitmap_ind16* src;
    bitmap_ind16* dest;

    /* The actual meaning of this conditional needs to be clarified: */
    if (srcPageId >= 0xFE || !((srcPageId &= 0xBF) & 0x80))
    {
        src = getPagePtr(srcPageId);
        dest = getPagePtr(dstPageId);
        for (int x=0; x < m_screen->width(); x++)
        {
            for (int y=0; y < m_screen->height(); y++)
            {
                dest->pix(y, x) = src->pix(y, x);
            }
        }
    }
    else
    {
        int h = m_screen->height();
        int src_y0 = 0;
        int dest_y0 = 0;
        src = getPagePtr(srcPageId & 3);
        dest = getPagePtr(dstPageId);
        if (vscroll >= -199 && vscroll <= 199)
        {
            if (vscroll < 0)
            {
                h += vscroll;
                src_y0 = -vscroll;
            }
            else
            {
                h -= vscroll;
                dest_y0 = vscroll;
            }
            for (int x=0; x < m_screen->width(); x++)
            {
                for (int y=0; y < h; y++)
                {
                    dest->pix(dest_y0 + y, x) = src->pix(src_y0 + y, x);
                }
            }
        }
    }
}
```

