    }
    else
    {
        uint8_t screen_resource_indexes[] = {
            0x12, 0x13, 0x43, 0x44,
            0x45, 0x46, 0x47, 0x48,
            0x49, 0x53, 0x90, 0x91
        };
        for (int i = 0; i < sizeof(screen_resource_indexes); i++)
        {
            if (screen_resource_indexes[i]==resourceId)
                ((another_world_vm_state*) owner())->loadScreen(i);
        }
    }
    return;
}
