   239→void tlcs900_device::state_string_export(const device_state_entry &entry, std::string &str) const
   240→{
   241→	switch (entry.index())
   242→	{
   243→		case STATE_GENFLAGS:
   244→			str = string_format("%c%d%c%d%c%c%c%c%c%c%c%c",
   245→					m_sr.w.l & 0x8000 ? 'S' : 'U',
   246→					( m_sr.w.l & 0x7000 ) >> 12,
   247→					m_sr.w.l & 0x0800 ? 'M' : 'N',
   248→					( m_sr.w.l & 0x0700 ) >> 8,
   249→					m_sr.w.l & 0x0080 ? 'S' : '.',
   250→					m_sr.w.l & 0x0040 ? 'Z' : '.',
   251→					m_sr.w.l & 0x0020 ? '1' : '.',
   252→					m_sr.w.l & 0x0010 ? 'H' : '.',
   253→					m_sr.w.l & 0x0008 ? '1' : '.',
   254→					m_sr.w.l & 0x0004 ? 'V' : '.',
   255→					m_sr.w.l & 0x0002 ? 'N' : '.',
   256→					m_sr.w.l & 0x0001 ? 'C' : '.' );
   257→			break;
   258→	}
   259→}
