   205→
   206→	/* XBC */
   207→	case 1:
   208→		return &m_xbc[m_regbank].d;
   209→
   210→	/* XDE */
   211→	case 2:
   212→		return &m_xde[m_regbank].d;
   213→
   214→	/* XHL */
   215→	case 3:
   216→		return &m_xhl[m_regbank].d;
   217→
   218→	/* XIX */
   219→	case 4:
